"""Snowflake Data Metric Functions — the first platform-native check engine
(ADR 0036 §6, #895 slice 2).
"""

from __future__ import annotations

from typing import Any

from backend.app.core.logging import get_logger
from backend.app.datasources.base import CheckOutcome
from backend.app.datasources.monitors import (
    FRESHNESS,
    MonitorConfigError,
    _ident,
    monitor_expectation_type,
)
from backend.app.services.failure_classifier import safe_failure_reason

log = get_logger(__name__)

DMF_ENGINE = "dmf"

# expectation-kind metric types → the system DMF that computes them.
DMF_COLUMN_METRICS: dict[str, str] = {
    "dmf:null_count": "NULL_COUNT",
    "dmf:null_percent": "NULL_PERCENT",
    "dmf:duplicate_count": "DUPLICATE_COUNT",
    "dmf:unique_count": "UNIQUE_COUNT",
    "dmf:blank_count": "BLANK_COUNT",
    "dmf:future_timestamp_percent": "FUTURE_TIMESTAMP_PERCENT",
}
# ACCEPTED_VALUES cannot be called ad hoc (it needs an attached, scheduled DMF), but
# SYSTEM$DATA_METRIC_SCAN evaluates it with no attachment and only SELECT rights (#2084).
DMF_ACCEPTED_VALUES = "dmf:accepted_values"
DMF_EXPECTATION_TYPES = (*DMF_COLUMN_METRICS, DMF_ACCEPTED_VALUES)
#: The config keys each dmf:* expectation type takes.
DMF_CONFIG_KEYS: dict[str, frozenset[str]] = {
    **{t: frozenset({"column"}) for t in DMF_COLUMN_METRICS},
    DMF_ACCEPTED_VALUES: frozenset({"column", "value_set"}),
}
_METRIC_NAMES = {**DMF_COLUMN_METRICS, DMF_ACCEPTED_VALUES: "ACCEPTED_VALUES"}
_MAX_ACCEPTED_VALUES = 500
_MAX_VALUE_CHARS = 1_000
# Higher-is-worse metrics band with thresholds; unique_count degrades DOWNWARD
# so thresholds are refused at author time (see module docstring).
DMF_UNBANDABLE_TYPES = frozenset({"dmf:unique_count"})
# The engine's supported-kind matrix (ADR 0036 §4). comparison / schema_drift / anomaly have run
# paths DMF cannot express (cross-dataset diff, introspection, baseline state).
DMF_KINDS = ("expectation", FRESHNESS)


def _quoted(name: object, *, what: str) -> str:
    """Validate (allowlist, #428 — via `_ident`, bounded echo) then quote (#476/#937)."""
    ident = _ident(name, what=what)
    return ident if ident == ident.lower() else f'"{ident}"'


def build_dmf_statement(
    *,
    kind: str,
    expectation_type: str,
    config: dict[str, Any],
    table: str,
    schema: str | None,
) -> str:
    """The ad-hoc invocation ``SELECT SNOWFLAKE.CORE.<FN>(SELECT … FROM <t>)``."""
    target = _quoted(table, what="table")
    if schema is not None:
        target = f"{_quoted(schema, what='schema')}.{target}"
    if kind == FRESHNESS:
        column = _quoted(config.get("column"), what="freshness column")
        return f"SELECT SNOWFLAKE.CORE.FRESHNESS(SELECT {column} FROM {target})"  # noqa: S608  # nosec B608
    function = DMF_COLUMN_METRICS.get(expectation_type)
    if kind != "expectation" or function is None:
        raise MonitorConfigError(
            f"the dmf engine cannot evaluate kind {kind!r} / type {expectation_type!r}"
        )
    column = _quoted(config.get("column"), what="column")
    return f"SELECT SNOWFLAKE.CORE.{function}(SELECT {column} FROM {target})"  # noqa: S608  # nosec B608


def _sql_literal(value: Any) -> str:
    """A value as a SQL literal inside the scan's expression: numbers bare, strings quoted."""
    if isinstance(value, bool) or value is None:
        raise MonitorConfigError("each accepted value must be a number or a string")
    if isinstance(value, int | float):
        return repr(value)
    if isinstance(value, str) and len(value) <= _MAX_VALUE_CHARS:
        # Snowflake string literals process backslash escapes, so a backslash is doubled before
        # the quote: `x\') OR TRUE --` must not close the literal early.
        return "'" + value.replace("\\", "\\\\").replace("'", "''") + "'"
    raise MonitorConfigError(
        f"each accepted value must be a number or a string of at most {_MAX_VALUE_CHARS}"
    )


def build_accepted_values_scan(
    config: dict[str, Any], *, table: str, schema: str | None
) -> tuple[str, dict[str, str]]:
    """``COUNT(*)`` over ``SYSTEM$DATA_METRIC_SCAN`` — the violating rows, NULLs excluded.

    Every argument is a bind parameter, so the only SQL DataQ assembles is the accepted-values
    expression, from an allowlisted column and escaped literals.
    """
    column = _quoted(config.get("column"), what="column")
    values = config.get("value_set")
    if not isinstance(values, list) or not 1 <= len(values) <= _MAX_ACCEPTED_VALUES:
        raise MonitorConfigError(
            f"'value_set' must be a list of 1 to {_MAX_ACCEPTED_VALUES} values"
        )
    target = _quoted(table, what="table")
    if schema is not None:
        target = f"{_quoted(schema, what='schema')}.{target}"
    statement = (
        "SELECT COUNT(*) FROM TABLE(SYSTEM$DATA_METRIC_SCAN("
        "REF_ENTITY_NAME => :ref, METRIC_NAME => 'SNOWFLAKE.CORE.ACCEPTED_VALUES', "
        "ARGUMENT_NAME => :arg, ARGUMENT_EXPRESSION => :expr))"
    )
    expression = f"{column} IN ({', '.join(_sql_literal(v) for v in values)})"
    return statement, {"ref": target, "arg": column, "expr": expression}


def _freshness_outcome(scalar: Any, config: dict[str, Any]) -> CheckOutcome:
    """Seconds-since-max → the monitor freshness outcome shape (age-hours metric)."""
    expectation_type = monitor_expectation_type(FRESHNESS)
    expected = {"monitor": FRESHNESS, "column": config.get("column"), "engine": DMF_ENGINE}
    if scalar is None:
        # An empty table has no max — same no-verdict rule as the monitor path.
        return CheckOutcome(
            expectation_type=expectation_type,
            success=False,
            errored=True,
            error_message="FRESHNESS returned no value (empty table?), freshness can't be assessed",
            expected_value=expected,
        )
    # Clamped at 0 like the monitor path (`_freshness_age_hours`): a max timestamp ahead of the
    # warehouse clock must trend 0.0 on BOTH engines, or the same data trends differently per
    # evaluator.
    age_hours = max(float(scalar) / 3600.0, 0.0)
    return CheckOutcome(
        expectation_type=expectation_type,
        success=True,  # binary fallback; thresholds band the age (authoring requires one)
        metric_value=age_hours,
        observed_value={"age_hours": round(age_hours, 3)},
        expected_value=expected,
    )


def _column_metric_outcome(
    scalar: Any, *, expectation_type: str, config: dict[str, Any]
) -> CheckOutcome:
    expected = {
        "engine": DMF_ENGINE,
        "metric": _METRIC_NAMES[expectation_type],
        "column": config.get("column"),
    }
    if scalar is None:
        return CheckOutcome(
            expectation_type=expectation_type,
            success=False,
            errored=True,
            error_message=f"{_METRIC_NAMES[expectation_type]} returned no value",
            expected_value=expected,
        )
    value = float(scalar)
    return CheckOutcome(
        expectation_type=expectation_type,
        success=True,  # thresholds band it (unique_count stays informational)
        metric_value=value,
        observed_value={"value": value},
        expected_value=expected,
    )


def evaluate_dmf_check(
    fetch_scalar: Any,
    *,
    kind: str,
    expectation_type: str,
    config: dict[str, Any],
    table: str,
    schema: str | None,
) -> CheckOutcome:
    """Evaluate ONE dmf-engine check; never raises — a failure is that check's
    classified ``error`` outcome (ADR 0036 §5), computed per check so a
    privilege problem on one metric never silences its siblings.
    """
    try:
        if kind == "expectation" and expectation_type == DMF_ACCEPTED_VALUES:
            statement, params = build_accepted_values_scan(config, table=table, schema=schema)
            scalar = fetch_scalar(statement, params)
            return _column_metric_outcome(scalar, expectation_type=expectation_type, config=config)
        statement = build_dmf_statement(
            kind=kind,
            expectation_type=expectation_type,
            config=config,
            table=table,
            schema=schema,
        )
        scalar = fetch_scalar(statement)
        if kind == FRESHNESS:
            return _freshness_outcome(scalar, config)
        return _column_metric_outcome(scalar, expectation_type=expectation_type, config=config)
    except Exception as exc:
        # Classified, never raw (#900): a Snowflake DMF failure text can carry the statement (and
        # DMF privilege errors name objects).
        return CheckOutcome(
            expectation_type=expectation_type,
            success=False,
            errored=True,
            error_message=_classify_dmf_error(exc),
        )


# The types NULL_COUNT is defined over (live `SHOW DATA METRIC FUNCTIONS`, 2026-09-27), as
# INFORMATION_SCHEMA.COLUMNS.DATA_TYPE spells them.
_PROBE_TARGET_BASE = (
    "SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
    "WHERE DATA_TYPE IN ('TEXT', 'NUMBER', 'FLOAT', 'DATE', 'TIMESTAMP_LTZ', "
    "'TIMESTAMP_NTZ', 'TIMESTAMP_TZ') AND TABLE_SCHEMA "
)
# The configured schema first, then anywhere else in the connection's database.
_PROBE_TARGET_QUERIES = (
    _PROBE_TARGET_BASE + "= CURRENT_SCHEMA() LIMIT 1",
    _PROBE_TARGET_BASE + "<> 'INFORMATION_SCHEMA' LIMIT 1",
)

DMF_AVAILABLE = "available"
DMF_NO_PRIVILEGE = "no_privilege"
DMF_UNSUPPORTED_EDITION = "unsupported_edition"
DMF_UNDETERMINED = "undetermined"


def _quote_identifier(name: str) -> str:
    return '"' + name.replace('"', '""') + '"'


def _undetermined(reason: str) -> dict[str, Any]:
    return {"available": None, "status": DMF_UNDETERMINED, "reason": reason}


def probe_dmf_capability(fetch_row: Any) -> dict[str, Any]:
    """Connection-test-time DMF availability probe (#1867, #2112). Never raises;
    the result is the `engine_capabilities["dmf"]` shape.

    An ad-hoc system-DMF call only accepts a bare column of a table or view, so the
    probe borrows one the role can already see and reads zero rows of it
    (``LIMIT 0``: compiled, privilege-checked, nothing scanned). ``available`` is
    ``None`` when the probe itself couldn't decide — never ``False``.
    """
    try:
        target = None
        for query in _PROBE_TARGET_QUERIES:
            target = fetch_row(query)
            if target:
                break
    except Exception as exc:
        log.warning("dmf_probe_target_lookup_failed", error_type=type(exc).__name__)
        return _undetermined(
            "couldn't list a table or view in the connection's database to probe DMF "
            "availability with — it is re-checked on the next connection test"
        )
    if not target:
        return _undetermined(
            "no table or view with a probe-able column is visible to this role in the "
            "connection's database, so DMF availability couldn't be checked — it is "
            "re-checked on the next connection test"
        )
    schema, table, column = (_quote_identifier(str(part)) for part in target)
    statement = f"SELECT SNOWFLAKE.CORE.NULL_COUNT(SELECT {column} FROM {schema}.{table} LIMIT 0)"  # noqa: S608  # nosec B608
    try:
        fetch_row(statement)
    except Exception as exc:
        return _classify_probe_failure(exc)
    return {"available": True, "status": DMF_AVAILABLE}


def _classify_probe_failure(exc: Exception) -> dict[str, Any]:
    text = str(exc)
    if "Unsupported feature" in text or "Enterprise Edition" in text:
        return {
            "available": False,
            "status": DMF_UNSUPPORTED_EDITION,
            "reason": "this Snowflake account's edition does not support data metric "
            "functions — DMFs need Enterprise Edition or higher",
        }
    if (
        "Unknown function" in text
        or "Insufficient privileges" in text
        or "SQL access control error" in text
    ):
        return {
            "available": False,
            "status": DMF_NO_PRIVILEGE,
            "reason": "the connection's role cannot invoke Snowflake system data metric "
            "functions — grant it the SNOWFLAKE.DATA_METRIC_USER database role",
        }
    # Anything else (a broken view, a timeout, an unrecognised message) says nothing about DMF
    # availability either way.
    log.warning("dmf_probe_inconclusive", error_type=type(exc).__name__)
    return _undetermined(
        "DMF availability couldn't be determined from the probe query — it is "
        "re-checked on the next connection test"
    )


_TEMPORAL_TYPES = "DATE, TIMESTAMP_LTZ and TIMESTAMP_TZ columns only"
_ARGUMENT_TYPE_GUIDANCE: dict[str, str] = {
    "FUTURE_TIMESTAMP_PERCENT": (
        f"Snowflake's FUTURE_TIMESTAMP_PERCENT data metric function accepts {_TEMPORAL_TYPES} "
        "— this column's type (commonly TIMESTAMP_NTZ) is not supported by the DMF."
    ),
    "BLANK_COUNT": (
        "Snowflake's BLANK_COUNT data metric function accepts VARCHAR columns only — "
        "point the check at a string column."
    ),
    "FRESHNESS": (
        f"Snowflake's FRESHNESS data metric function accepts {_TEMPORAL_TYPES} — this "
        "column's type (commonly TIMESTAMP_NTZ) is not supported by the DMF. Use the "
        "GX-engine freshness monitor for this column instead."
    ),
}


def _classify_dmf_error(exc: Exception) -> str:
    """Fixed guidance for the DMF failure shapes live testing surfaced —
    Snowflake's own messages either mislead when generically classified (an
    unknown column read as "connection misconfigured") or name a limitation
    the author can only fix by knowing the platform rule.
    """
    text = str(exc)
    if "Invalid argument types" in text:
        for function, guidance in _ARGUMENT_TYPE_GUIDANCE.items():
            if function in text:
                return guidance
    if "invalid identifier" in text or "does not exist or not authorized" in text:
        # The second shape is Snowflake's missing-TABLE error (002003) — its "or not authorized"
        # tail must not fall through to the privilege branch below.
        return (
            "the configured column or table does not exist on the run target "
            "(or the role cannot see it) — check the check's column and the "
            "suite's run target"
        )
    if "Unknown function" in text or "not authorized" in text or "Insufficient privileges" in text:
        return (
            "the connection's role cannot invoke Snowflake system data metric "
            "functions — DMFs need Enterprise Edition and the "
            "SNOWFLAKE.DATA_METRIC_USER database role (or EXECUTE DATA METRIC "
            "FUNCTION) granted to the connection's role"
        )
    return safe_failure_reason(exc)
"""Connection-anchored check-engine capability map (ADR 0036)."""

from __future__ import annotations

from backend.app.datasources.sql_engines import GENERIC_SQL_TYPES
from backend.app.db.models import GX_ENGINE

# Datasource connection types only — an orchestration provider offers no engines (it has no checks).
_OFFERED: dict[str, frozenset[str]] = {
    # 'dmf' rides SnowflakeCheckRunner.run_native_check (ADR 0036 §6, #895);
    # `test_offered_native_engines_are_runnable` pins offer ⇔ runner support.
    "snowflake": frozenset({GX_ENGINE, "dmf"}),
    "adls_gen2": frozenset({GX_ENGINE}),
    "s3": frozenset({GX_ENGINE}),
    # 'dqx' rides UnityCatalogCheckRunner.run_native_checks: a serverless job in the workspace.
    "unity_catalog": frozenset({GX_ENGINE, "dqx"}),
    "iceberg": frozenset({GX_ENGINE}),
    # The generic SQL engines (#1678) have no native DQ engine to offer.
    **{conn_type: frozenset({GX_ENGINE}) for conn_type in GENERIC_SQL_TYPES},
}


def engines_for(connection_type: str) -> frozenset[str]:
    """Engines ``connection_type`` offers; empty for a non-datasource type."""
    return _OFFERED.get(connection_type, frozenset())

    return SnowflakeDialect().normalize_name(name) or name


def _fold_reflection_keyed_columns(checks: list[CheckSpec]) -> list[CheckSpec]:
    return fold_reflection_keyed_columns(
        checks, REDACTED, normalize_name=_reflection_key
    )


class SnowflakeCheckRunner:
    """`CheckRunner` for Snowflake. Building the asset connects to the warehouse."""

    # Runner-advertised monitor capability (#429): EXPLICITLY what this runner implements — never
    # frozenset(MONITOR_KINDS).
    supported_monitor_kinds: ClassVar[frozenset[str]] = frozenset({FRESHNESS, VOLUME})
    # Native engines this runner evaluates (ADR 0036): the run path routes a check whose `engine` is
    # advertised here to `run_native_check`; anything else lands as a classified per-check error.
    supported_native_engines: ClassVar[frozenset[str]] = frozenset({DMF_ENGINE})
    # The run path hands a `value_signal_gate` only to runners advertising it (#2014).
    accepts_value_signal_gate: ClassVar[bool] = True

    def __init__(self, config: SnowflakeConfig, secret: str) -> None:
        self._config = config
        self._connection_string = build_connection_string(config, secret)
        # Key-pair auth: the loaded DER private key (under 'private_key'), consumed by the shared
        # engine's connect-args and re-encoded for the GX kwargs form in run_checks.
        self._connect_args = build_connect_args(config, secret)
        # The runner's ONE lazily-built engine (#427) — every non-GX SQL touchpoint shares it (and
        # its pooled session) instead of paying a fresh engine + auth handshake per call.
        self._engine = LazyEngine(self._build_engine)

    def _build_engine(self) -> Any:
        from sqlalchemy import create_engine

        # pool_pre_ping: the pooled session can sit idle across a long GX validation in a mixed
        # suite — revalidate on checkout so a warehouse-side idle reap surfaces as a fresh connect.
        return create_engine(
            self._connection_string,
            connect_args=self._connect_args or {},
            pool_pre_ping=True,
        )

    def close(self) -> None:
        """Dispose the shared engine's pool. Idempotent; a no-op if never used."""
        self._engine.close()

    def run_checks(
        self,
        *,
        table: str,
        schema: str | None,
        checks: list[CheckSpec],
        index_columns: list[str] | None = None,
        value_signal_gate: ValueSignalGate | None = None,
    ) -> SuiteOutcome:
        with ephemeral_gx_context() as context:
            if self._config.auth_type == "key_pair":
                # GX 1.17's supported key-pair form (KeyPairConnectionDetails): the connection as
                # keyword args with a base64-DER private_key.
                datasource = context.data_sources.add_snowflake(
                    name=f"sf-{table}",
                    account=self._config.account,
                    user=self._config.user,
                    database=self._config.database,
                    schema=self._config.schema_,
                    warehouse=self._config.warehouse,
                    role=self._config.role,
                    private_key=base64.standard_b64encode(
                        self._connect_args["private_key"]
                    ).decode(),
                )
            else:
                datasource = context.data_sources.add_snowflake(
                    name=f"sf-{table}",
                    connection_string=self._connection_string,
                )
            asset = datasource.add_table_asset(
                name=table,
                table_name=table,
                schema_name=schema or self._config.schema_,
            )
            # The table asset resolves its own batch, so no batch_parameters; the
            # ephemeral context makes the fixed suite/vd names safe across runs.
            batch_definition = asset.add_batch_definition_whole_table(name="whole_table")
            return run_expectations(
                context,
                batch_definition=batch_definition,
                checks=_fold_reflection_keyed_columns(checks),
                name=f"suite-{table}",
                # index_columns deliberately NOT folded: live-verified 2026-08-28 that GX's
                # unexpected_index_column_names path accepts the authored (upper) casing and keys
                # the locators by it — folding would lowercase the locator keys users see.
                index_columns=index_columns,
                value_signal_gate=value_signal_gate,
            )

    def run_native_check(
        self,
        *,
        kind: str,
        expectation_type: str,
        config: dict[str, Any],
        table: str,
        schema: str | None,
    ) -> CheckOutcome:
        """Evaluate ONE dmf-engine check via ad-hoc system-DMF SQL (ADR 0036)."""
        from sqlalchemy import text

        with self._engine.get().connect() as conn:
            return evaluate_dmf_check(
                lambda statement, params=None: conn.execute(text(statement), params or {}).scalar(),
                kind=kind,
                expectation_type=expectation_type,
                config=config,
                table=table,
                schema=schema or self._config.schema_,
            )

    def run_monitors(
        self, *, table: str, schema: str | None, monitors: list[MonitorSpec]
    ) -> list[CheckOutcome]:
        """Evaluate freshness/volume monitors via scalar SQL aggregates (no GX)."""
        return run_monitors_over_engine(
            self._engine.get(),
            table=table,
            schema=schema or self._config.schema_,
            catalog=None,
            monitors=monitors,
        )


def build_snowflake_runner(
    *,
    config: dict[str, Any],
    secret_ref: str | None,
    secret_store: SecretStore,
) -> SnowflakeCheckRunner:
    """Build a runner from a `Connection` row's config + secret_ref."""
    if not secret_ref:
        raise ValueError("Snowflake connection requires secret_ref for the password / private key")
    sf_config = SnowflakeConfig.model_validate(config)
    secret = secret_store.get(secret_ref)
    return SnowflakeCheckRunner(sf_config, secret)


# Snowflake connector timeouts (seconds) for the connectivity test — fail fast
# rather than hanging the request thread on an unreachable account.
_TEST_LOGIN_TIMEOUT = 10
_TEST_NETWORK_TIMEOUT = 10


class SnowflakeConnectionAdapter:
    """`ConnectionAdapter` for Snowflake — config validation + a SELECT 1 test."""

    # #1401: `account` becomes `<account>.snowflakecomputing.com`, so it decides which host receives
    # the password/key-pair.
    destination_fields: ClassVar[dict[str, tuple[str, ...]]] = {"secret": ("account",)}

    def validate_config(self, raw: dict[str, Any]) -> SnowflakeConfig:
        return SnowflakeConfig.model_validate(raw)

    def test(
        self,
        raw: dict[str, Any],
        secret: str | None,
        *,
        capability_probe: Callable[[Any], None] | None = None,
        **_: Any,
    ) -> None:
        """Open a connection and run ``SELECT 1``; raise on any failure.

        ``capability_probe``, when given, runs on the SAME connection right after
        (#1867 review) — a second `test`-time login for the DMF probe would double
        every Test/Reauth click's latency for no reason, since both need nothing
        but a live session.
        """
        if secret is None:
            raise ValueError("a credential is required to test a snowflake connection")
        from sqlalchemy import create_engine, text

        config = self.validate_config(raw)
        engine = create_engine(
            build_connection_string(config, secret),
            connect_args={
                "login_timeout": _TEST_LOGIN_TIMEOUT,
                "network_timeout": _TEST_NETWORK_TIMEOUT,
                **build_connect_args(config, secret),
            },
        )
        try:
            with engine.connect() as conn:
                conn.execute(text("SELECT 1"))
                if capability_probe is not None:
                    capability_probe(conn)
        finally:
            engine.dispose()

    def probe_dmf(self, raw: dict[str, Any], secret: str | None) -> dict[str, Any]:
        """DMF availability (#1867), on an ALREADY-verified-live connection —
        callers only invoke this after `test` succeeds. Prefer passing
        `capability_probe` to `test()` instead when both run in the same
        request, to avoid a second Snowflake login.
        """
        from sqlalchemy import create_engine

        if secret is None:
            raise ValueError("a credential is required to probe DMF availability")
        config = self.validate_config(raw)
        engine = create_engine(
            build_connection_string(config, secret),
            connect_args={
                "login_timeout": _TEST_LOGIN_TIMEOUT,
                "network_timeout": _TEST_NETWORK_TIMEOUT,
                **build_connect_args(config, secret),
            },
        )
        try:
            with engine.connect() as conn:
                return self._probe_dmf_on_connection(conn)
        finally:
            engine.dispose()

    @staticmethod
    def _probe_dmf_on_connection(conn: Any) -> dict[str, Any]:
        from sqlalchemy import text

        return probe_dmf_capability(lambda stmt: conn.execute(text(stmt)).first())
            f"the dqx engine cannot evaluate kind {kind!r} — it evaluates the dqx:* checks",
            detail={"engine": DQX_ENGINE, "kind": kind, "supported_kinds": sorted(DQX_KINDS)},
        )
    if expectation_type not in DQX_EXPECTATION_TYPES:
        raise CheckConfigInvalidError(
            f"expectation_type {expectation_type!r} is not a dqx check",
            detail={"engine": DQX_ENGINE, "supported_types": sorted(DQX_EXPECTATION_TYPES)},
        )
    try:
        build_dqx_rule(expectation_type, config)
    except DqxConfigError as exc:
        raise CheckConfigInvalidError(
            exc.message, detail={"expectation_type": expectation_type}
        ) from exc


def validate_engine_compatibility(
    engine: str,
    *,
    kind: str,
    expectation_type: str,
    config: dict[str, Any],
    warn_threshold: Decimal | None,
    fail_threshold: Decimal | None,
    critical_threshold: Decimal | None,
) -> None:
    """The engine's supported matrix (ADR 0036 §4) — 422 for a kind/type/config
    the engine cannot evaluate. Shared by create, update, restore and suite
    import (the one-gate-per-rule discipline).
    """
    if engine == DQX_ENGINE:
        _validate_dqx(kind=kind, expectation_type=expectation_type, config=config)
        return
    if engine != DMF_ENGINE:
        return
    if kind not in DMF_KINDS:
        raise CheckConfigInvalidError(
            f"the dmf engine cannot evaluate kind {kind!r} — it evaluates "
            "freshness and the dmf:* column metrics",
            detail={"engine": engine, "kind": kind, "supported_kinds": sorted(DMF_KINDS)},
        )
    if kind != "expectation":
        return  # freshness/volume config is the monitor validators' job
    if expectation_type not in DMF_EXPECTATION_TYPES:
        raise CheckConfigInvalidError(
            f"expectation_type {expectation_type!r} is not a dmf metric",
            detail={"engine": engine, "supported_types": sorted(DMF_EXPECTATION_TYPES)},
        )
    keys = DMF_CONFIG_KEYS[expectation_type]
    unknown_keys = sorted(set(config) - keys)
    if unknown_keys:
        raise CheckConfigInvalidError(
            f"a {expectation_type} config takes exactly {sorted(keys)}; unknown keys: "
            f"{', '.join(unknown_keys)}",
            detail={"expectation_type": expectation_type, "unknown_keys": unknown_keys},
        )
    if expectation_type == DMF_ACCEPTED_VALUES:
        try:
            build_accepted_values_scan(config, table="t", schema=None)
        except MonitorConfigError as exc:
            raise CheckConfigInvalidError(
                str(exc), detail={"expectation_type": expectation_type}
            ) from exc
    if not is_sql_identifier(config.get("column")):
        raise CheckConfigInvalidError(
            "a dmf column metric needs a valid 'column' identifier in config",
            detail={"expectation_type": expectation_type},
        )
    thresholds_set = any(
        t is not None for t in (warn_threshold, fail_threshold, critical_threshold)
    )
    if expectation_type in DMF_UNBANDABLE_TYPES:
        if thresholds_set:
            raise CheckConfigInvalidError(
                f"{expectation_type} does not accept thresholds: severity bands treat a "
                "higher metric as worse, but a unique count degrades DOWNWARD — a "
                "threshold would invert its meaning. It records the metric for trends.",
                detail={"expectation_type": expectation_type},
            )
    elif not _has_positive_threshold(fail_threshold, critical_threshold):
        raise CheckConfigInvalidError(
            f"a {expectation_type} check needs a positive fail or critical threshold — "
            "without one it can never fail (no threshold) or always fails (zero)",
            detail={"expectation_type": expectation_type},
        )


def validate_dimension(dimension: str | None) -> str | None:
    """Reject a DQ dimension outside the seven canonical ones (422), ADR 0038."""
    if dimension is not None and not is_valid_dimension(dimension):
        raise CheckConfigInvalidError(
            f"unknown DQ dimension {str(dimension)[:_ERROR_ECHO_MAX_CHARS]!r}",
            detail={
                "dimension": str(dimension)[:_ERROR_ECHO_MAX_CHARS],
                "supported": sorted(DQ_DIMENSIONS),
            },
        )
    return dimension


