def list_custom_dmfs(fetch_all: Any) -> dict[str, Any]:
    """The ``custom_functions`` part of the ``dmf`` capability. Never raises.

    ``custom_functions`` is ``None`` when the listing itself failed (with a reason), else the
    visible DMFs outside the ``SNOWFLAKE`` database whose names DataQ can reference.
    """
    try:
