    except Exception as exc:
        log.warning("dmf_custom_listing_failed", error_type=type(exc).__name__)
        return {
            "custom_functions": None,
            "custom_functions_reason": "custom DMFs couldn't be listed for this connection's "
            "role — you can still name one; it is re-listed on the next connection test",
        }
    listed: list[dict[str, str]] = []
    unreferenceable = 0
    seen: set[tuple[str, str]] = set()
    for row in rows:
        database, schema, name = (str(row.get(k) or "") for k in ("catalog_name", "schema_name", "name"))
        if database.upper() == "SNOWFLAKE":
