        # quoted in lower case would fold to upper case and miss.
        if not all(is_sql_identifier(p) and p != p.lower() or p.isupper() for p in parts):
            unreferenceable += 1
            continue
        qualified = ".".join(parts)
        arguments = str(row.get("arguments") or "")
        signature = arguments[len(name) :] if arguments.startswith(name) else arguments
        signature = signature.strip()[:_MAX_SIGNATURE_CHARS]
        if (qualified, signature) in seen:
            continue
        seen.add((qualified, signature))
        listed.append({"name": qualified, "signature": signature})
    listed.sort(key=lambda f: (f["name"], f["signature"]))
    result: dict[str, Any] = {
        "custom_functions": listed[:MAX_LISTED_CUSTOM_DMFS],
        "custom_functions_truncated": len(listed) > MAX_LISTED_CUSTOM_DMFS,
    }
    if unreferenceable:
        result["custom_functions_unlisted"] = unreferenceable
    return result
