import type { CheckCreate } from '../../api/suites';

import { COMPARISON_EXPECTATION_TYPE, fieldVisible } from './expectationCatalog';
import { EXPECTATION_BY_TYPE, type DqDimension, type ExpectationSpec } from './expectationCatalog';

/**
 * Pure check-authoring form helpers shared by the edit page (`CheckEdit`) and the create page
 * (`CheckNew`): the form↔payload conversions, so the two surfaces can't drift on kwarg shaping.
 */

/** Split a comma-separated list field into trimmed, non-empty items. */
export function parseList(value: unknown): string[] {
  return String(value ?? '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

function numOrNull(v: unknown): number | null {
  return typeof v === 'number' ? v : null;
}

/** Build the GX `config` kwargs from only the selected expectation's fields. */
function formToConfig(
  spec: ExpectationSpec | undefined,
  raw: Record<string, unknown>,
): Record<string, unknown> {
  const config: Record<string, unknown> = {};
  if (!spec) return config;
  for (const field of spec.fields) {
    // A conditionally-hidden field (anomaly's `column`, #593) must never be submitted even if
    // antd's Form preserved a stale value from before the author switched target_metric away.
    if (!fieldVisible(field, raw)) continue;
    const value = raw[field.name];
    if (value === undefined || value === null || value === '') continue;
    if (field.type === 'list') {
      const items = parseList(value);
      if (items.length > 0) config[field.name] = items;
    } else {
      config[field.name] = value;
    }
  }
  return config;
}

/** Inverse of formToConfig for edit-mode prefill (list array → comma string). */
export function configToForm(
  spec: ExpectationSpec | undefined,
  config: Record<string, unknown>,
): Record<string, unknown> {
  const form: Record<string, unknown> = {};
  if (!spec) return form;
  for (const field of spec.fields) {
    const value = config[field.name];
    if (value === undefined) continue;
    form[field.name] = field.type === 'list' && Array.isArray(value) ? value.join(', ') : value;
  }
  return form;
}

/** Assemble the create/update payload from validated form values. */
export function buildCheckPayload(values: Record<string, unknown>): CheckCreate {
  const spec = EXPECTATION_BY_TYPE[values.expectation_type as string];
  return {
    name: values.name as string,
    // The monitor kinds (freshness/volume) carry a non-default kind; expectations
    // (incl. custom-SQL) stay 'expectation'. The backend defaults to 'expectation'.
    kind: spec?.kind ?? 'expectation',
    // engine: 'gx' unless Freshness's picker (values.engine) or the spec fixes otherwise.
    engine: (values.engine as string | undefined) ?? spec?.engine ?? 'gx',
    expectation_type: values.expectation_type as string,
    config: formToConfig(spec, (values.config ?? {}) as Record<string, unknown>),
    // ADR 0038.
    dimension: (values.dimension as DqDimension | undefined) ?? undefined,
    // A noThresholds type never submits thresholds — stale form values from a
    // type switch would otherwise ride along and be refused server-side.
    warn_threshold: spec?.noThresholds ? null : numOrNull(values.warn_threshold),
    fail_threshold: spec?.noThresholds ? null : numOrNull(values.fail_threshold),
    critical_threshold: spec?.noThresholds ? null : numOrNull(values.critical_threshold),
  };

